    ('24ab8a47-7d3a-5506-b9cc-3ac7efd38a90'::uuid, 'Quiz — Le plus court chemin dans un graphe', 'SNT', '2de', 'Calcul d’itinéraire', '281d0de5-5721-528f-81bd-015cff035998'::uuid),
    ('d199fb1f-8926-5b1e-a9af-82d4d147ebf7'::uuid, 'Quiz — Capter, décider, agir', 'SNT', '2de', 'Systèmes automatisés', '364fa55d-c386-582e-983e-bcebc497ce0f'::uuid),
    ('a40d9c14-cf25-55ca-9ccc-7bea5e97f93f'::uuid, 'Quiz — Quand les objets se mettent à parler au réseau', 'SNT', '2de', 'L’Internet des objets (ou IoT)', '5d86f75e-71df-5c9f-ba45-9db8c0e3d250'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('acb81efd-9887-5955-8c85-c81c79f77c23'::uuid, '6cb97561-2ec4-591b-adc1-3f069c93d7bd'::uuid, 'Qu’est-ce qu’Internet ?', 'mcq', '["Un réseau de réseaux reliés par des protocoles communs","Un ordinateur central géant","Une entreprise américaine","Un ensemble de pages web"]'::jsonb, 0, 'Aucune entité ne le possède ni ne le contrôle entièrement.', 1),
    ('2a015861-d826-5fd3-b3b4-7448c2f34f0a'::uuid, '6cb97561-2ec4-591b-adc1-3f069c93d7bd'::uuid, 'Comment s’appelle l’ancêtre d’Internet créé en 1969 ?', 'mcq', '["ARPANET","CERN","NSFNET","MINITEL"]'::jsonb, 0, 'Il reliait quatre universités américaines.', 2),
    ('f4e1ada1-d512-56be-b2d1-4fbbbfa8b53d'::uuid, '6cb97561-2ec4-591b-adc1-3f069c93d7bd'::uuid, 'Qu’est-ce que la commutation de paquets ?', 'mcq', '["Le découpage d’un message en paquets voyageant indépendamment","Le chiffrement des messages","La compression des fichiers","La duplication des serveurs"]'::jsonb, 0, 'Les paquets sont réassemblés à l’arrivée.', 3),
    ('e5943f06-78ee-598d-a8db-4b2def446ac4'::uuid, '6cb97561-2ec4-591b-adc1-3f069c93d7bd'::uuid, 'Pourquoi Internet est-il résilient ?', 'mcq', '["Si un lien tombe, les paquets empruntent un autre chemin","Parce que les données sont sauvegardées","Parce qu’il est chiffré","Parce qu’un centre le supervise"]'::jsonb, 0, 'L’absence de centre est un choix de conception.', 4),
    ('65131e60-44c0-5ea9-aa70-56a8c464e0d9'::uuid, '6cb97561-2ec4-591b-adc1-3f069c93d7bd'::uuid, 'Combien de couches compte le modèle TCP/IP ?', 'mcq', '["Quatre","Sept","Deux","Cinq"]'::jsonb, 0, 'Accès réseau, Internet, transport, application.', 5),
    ('025352de-1b72-5466-b658-ea8ba345db7b'::uuid, '6cb97561-2ec4-591b-adc1-3f069c93d7bd'::uuid, 'Internet et le Web sont deux choses différentes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Internet est l’infrastructure, le Web une application parmi d’autres.', 6),
    ('b903203e-b89b-5d1d-a217-89b1a105b0ca'::uuid, '6cb97561-2ec4-591b-adc1-3f069c93d7bd'::uuid, 'Qui a inventé le Web en 1989 ?', 'mcq', '["Tim Berners-Lee, au CERN","Vinton Cerf","Steve Jobs","Linus Torvalds"]'::jsonb, 0, 'Il y invente aussi le premier navigateur et le premier serveur.', 7),
    ('41181a9b-d3b8-5d69-b014-07b24c1aa769'::uuid, '6cb97561-2ec4-591b-adc1-3f069c93d7bd'::uuid, 'En quelle année TCP/IP devient-il le protocole commun d’Internet ?', 'mcq', '["1983","1969","1989","1995"]'::jsonb, 0, 'C’est la date de naissance d’Internet au sens actuel.', 8),
    ('fd414072-4a05-509c-a68f-b8e775301021'::uuid, '61cc4d29-b677-53cd-91bc-487c30960020'::uuid, 'Sur combien de bits une adresse IPv4 est-elle codée ?', 'mcq', '["32 bits","64 bits","128 bits","16 bits"]'::jsonb, 0, 'Soit quatre nombres de 0 à 255.', 1),
    ('1bb9015a-ce77-5183-a442-9e87f23e4a7b'::uuid, '61cc4d29-b677-53cd-91bc-487c30960020'::uuid, 'Combien d’adresses IPv4 existent environ ?', 'mcq', '["Environ 4,3 milliards","Environ 4 millions","Un nombre illimité","Environ 300 millions"]'::jsonb, 0, 'Insuffisant depuis longtemps, d’où IPv6.', 2),
    ('4f8c1396-276c-5f5d-b07a-ade8af6df829'::uuid, '61cc4d29-b677-53cd-91bc-487c30960020'::uuid, 'Sur combien de bits une adresse IPv6 est-elle codée ?', 'mcq', '["128 bits","32 bits","64 bits","256 bits"]'::jsonb, 0, 'Elle s’écrit en hexadécimal, séparée par des deux-points.', 3),
    ('37af2326-d31e-5531-95ca-4f50c72d91a1'::uuid, '61cc4d29-b677-53cd-91bc-487c30960020'::uuid, 'Que sépare le masque de sous-réseau ?', 'mcq', '["La partie réseau et la partie hôte d’une adresse","L’adresse publique et l’adresse privée","Le nom de domaine et l’adresse IP","Le protocole et le port"]'::jsonb, 0, 'Il indique quelles machines sont sur le même réseau local.', 4),
    ('8f1fbd04-f0bc-5d36-95a6-4d8c2b5650f6'::uuid, '61cc4d29-b677-53cd-91bc-487c30960020'::uuid, 'Quel protocole attribue automatiquement une adresse IP à un appareil qui se connecte ?', 'mcq', '["DHCP","DNS","HTTP","FTP"]'::jsonb, 0, 'La box l’utilise pour vos appareils domestiques.', 5),
    ('4f0246a4-3bda-5731-8334-131802a85f5d'::uuid, '61cc4d29-b677-53cd-91bc-487c30960020'::uuid, 'Une adresse commençant par 192.168 est une adresse privée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle ne circule pas sur Internet ; le NAT fait la traduction.', 6),
    ('62e9e9a7-b6af-5e74-8124-9dcfa23c2a24'::uuid, '61cc4d29-b677-53cd-91bc-487c30960020'::uuid, 'À quoi sert le DNS ?', 'mcq', '["À traduire un nom de domaine en adresse IP","À chiffrer les échanges","À router les paquets","À attribuer les adresses"]'::jsonb, 0, 'C’est l’annuaire d’Internet.', 7),
    ('802f0584-fdc1-5a83-aa6f-52e0cebde92f'::uuid, '61cc4d29-b677-53cd-91bc-487c30960020'::uuid, 'Une adresse IP identifie-t-elle une personne ?', 'mcq', '["Non, elle identifie une machine ou un accès à un instant donné","Oui, précisément","Oui, avec le nom de domaine","Non, elle est aléatoire"]'::jsonb, 0, 'Elle reste une donnée personnelle au sens du RGPD, car indirectement identifiante.', 8),
    ('6d52033e-ee3d-55d0-8359-d3c868f03833'::uuid, '7a3d26d0-47cb-5b59-8ef8-22c2abf18f25'::uuid, 'Que fait un routeur ?', 'mcq', '["Il choisit vers quel réseau voisin envoyer chaque paquet","Il chiffre les données","Il attribue les adresses IP","Il stocke les pages web"]'::jsonb, 0, 'Il s’appuie sur sa table de routage.', 1),
    ('9f4e5032-82e5-5a17-b56e-2996c09c59c3'::uuid, '7a3d26d0-47cb-5b59-8ef8-22c2abf18f25'::uuid, 'Qu’est-ce qu’une table de routage ?', 'mcq', '["Une table associant des destinations à des directions à emprunter","La liste des sites visités","La liste des adresses privées","Un annuaire de noms de domaine"]'::jsonb, 0, 'Mise à jour par des protocoles comme OSPF ou BGP.', 2),
    ('16fb73e5-2fe2-5445-8a24-dd2792ac0a70'::uuid, '7a3d26d0-47cb-5b59-8ef8-22c2abf18f25'::uuid, 'Que garantit le protocole TCP ?', 'mcq', '["L’arrivée complète et ordonnée des paquets","La rapidité maximale","Le chiffrement des échanges","L’anonymat de l’expéditeur"]'::jsonb, 0, 'Numérotation, accusés de réception, retransmission.', 3),
    ('8ed578e2-46aa-5989-9eb4-760063970439'::uuid, '7a3d26d0-47cb-5b59-8ef8-22c2abf18f25'::uuid, 'Quel protocole est préféré pour le jeu en ligne ou la visioconférence ?', 'mcq', '["UDP","TCP","DNS","DHCP"]'::jsonb, 0, 'Mieux vaut une donnée perdue qu’une donnée en retard.', 4),
    ('694f8517-a09d-5121-8070-8942c3d3ae92'::uuid, '7a3d26d0-47cb-5b59-8ef8-22c2abf18f25'::uuid, 'Tous les paquets d’un même message suivent-ils le même chemin ?', 'mcq', '["Non, ils peuvent emprunter des routes différentes","Oui, toujours","Oui, sauf en cas de panne","Non, ils suivent tous le plus court en distance"]'::jsonb, 0, 'Ils sont réassemblés à l’arrivée.', 5),
    ('158c5f8e-1fb1-5786-a5dd-d93e164d1e11'::uuid, '7a3d26d0-47cb-5b59-8ef8-22c2abf18f25'::uuid, 'La commande traceroute permet de visualiser les routeurs traversés.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle affiche chaque saut et son temps de réponse.', 6),
    ('2a06e1b9-3429-530b-bb36-85349b07b170'::uuid, '7a3d26d0-47cb-5b59-8ef8-22c2abf18f25'::uuid, 'Sur quoi se fonde le choix d’une route ?', 'mcq', '["Un coût calculé : nombre de sauts, débit, latence","La distance géographique uniquement","Le hasard","Le choix de l’utilisateur"]'::jsonb, 0, 'Le chemin le plus court n’est pas le plus direct sur la carte.', 7),
    ('2d616511-9964-53b4-b64f-de9ddf21667c'::uuid, '7a3d26d0-47cb-5b59-8ef8-22c2abf18f25'::uuid, 'Que fait TCP quand un paquet n’arrive pas ?', 'mcq', '["Il le redemande à l’expéditeur","Il abandonne le message","Il le remplace par un paquet vide","Il change de protocole"]'::jsonb, 0, 'L’accusé de réception manquant déclenche la retransmission.', 8),
    ('ddfcca5a-c0bd-519e-8bb0-91a340e6ed84'::uuid, '2b493899-175e-54d7-ba59-4002112dfb46'::uuid, 'Dans le modèle client-serveur, que fait le serveur ?', 'mcq', '["Il attend des requêtes et y répond","Il envoie des données sans être sollicité","Il télécharge auprès des clients","Il route les paquets"]'::jsonb, 0, 'Le client demande, le serveur fournit.', 1),
    ('b6e9afd2-9bca-50ba-8e3a-5cbb195a1470'::uuid, '2b493899-175e-54d7-ba59-4002112dfb46'::uuid, 'Quelle est la principale faiblesse du modèle client-serveur ?', 'mcq', '["Le serveur est un point unique de défaillance","Il est trop lent en lecture","Il ne permet pas la mise à jour","Il ne fonctionne pas sur Internet"]'::jsonb, 0, 'Panne ou saturation privent tous les clients du service.', 2),
    ('271b6c9f-0470-5506-b146-2a39f2bae565'::uuid, '2b493899-175e-54d7-ba59-4002112dfb46'::uuid, 'Qu’est-ce qu’une attaque par déni de service ?', 'mcq', '["Une saturation volontaire d’un serveur par un flot de requêtes","Un vol de mot de passe","Un chiffrement des données","Une usurpation d’adresse IP"]'::jsonb, 0, 'Le service devient indisponible pour les utilisateurs légitimes.', 3),
    ('5da5bbd2-c445-5836-aeb4-210f99ac50c2'::uuid, '2b493899-175e-54d7-ba59-4002112dfb46'::uuid, 'Dans un réseau pair-à-pair, quel est le rôle de chaque machine ?', 'mcq', '["Elle est à la fois client et serveur","Elle est uniquement cliente","Elle est uniquement serveur","Elle sert de routeur"]'::jsonb, 0, 'Elle télécharge et fournit simultanément.', 4),
    ('5bc71043-68fe-5f54-b1c9-f70e6153fc2a'::uuid, '2b493899-175e-54d7-ba59-4002112dfb46'::uuid, 'Que se passe-t-il dans un réseau pair-à-pair quand le nombre de participants augmente ?', 'mcq', '["Le réseau devient plus rapide et plus robuste","Il ralentit comme un serveur","Il se bloque","Rien ne change"]'::jsonb, 0, 'C’est l’inverse du modèle client-serveur.', 5),
    ('f99e9276-9fb0-56fe-9be3-6d35beb588bd'::uuid, '2b493899-175e-54d7-ba59-4002112dfb46'::uuid, 'Le pair-à-pair rend le contrôle des contenus plus difficile.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où son usage pour le partage illégal d’œuvres protégées.', 6),
    ('59b85063-54ba-54ce-b556-654285fa2797'::uuid, '2b493899-175e-54d7-ba59-4002112dfb46'::uuid, 'Quel service repose sur le modèle client-serveur ?', 'mcq', '["Le Web","Une crypto-monnaie","Un partage de fichiers en torrent","Un réseau maillé décentralisé"]'::jsonb, 0, 'Le navigateur est le client, le site le serveur.', 7),
    ('379bac64-c026-5480-80a8-f709ff93df4c'::uuid, '2b493899-175e-54d7-ba59-4002112dfb46'::uuid, 'Un service peut-il combiner les deux modèles ?', 'mcq', '["Oui, serveur central pour l’annuaire et pair-à-pair pour les transferts","Non, ils sont incompatibles","Oui, mais seulement en local","Non, sauf en entreprise"]'::jsonb, 0, 'C’est le cas de nombreuses plateformes de visioconférence.', 8),
    ('0663d5f9-cf46-529b-a48a-043c44cfe285'::uuid, 'a5b34236-2540-55ae-b6c1-89764b95738b'::uuid, 'Qu’est-ce que l’hypertexte ?', 'mcq', '["Un texte comportant des liens vers d’autres documents","Un texte très long","Un texte chiffré","Un texte enrichi de couleurs"]'::jsonb, 0, 'Le lien est une adresse activable.', 1),
    ('7f2bd9e5-4d3f-52a9-aaee-fed0f067955b'::uuid, 'a5b34236-2540-55ae-b6c1-89764b95738b'::uuid, 'En quelle année Tim Berners-Lee propose-t-il le Web ?', 'mcq', '["1989","1969","1945","1995"]'::jsonb, 0, 'Au CERN, pour relier les documents des laboratoires.', 2),
    ('ca713044-783f-5fa8-9db1-4428cc32ca49'::uuid, 'a5b34236-2540-55ae-b6c1-89764b95738b'::uuid, 'Quelles sont les trois briques fondatrices du Web ?', 'mcq', '["URL, HTTP et HTML","IP, TCP et DNS","HTML, CSS et JavaScript","DNS, DHCP et NAT"]'::jsonb, 0, 'Adresser, transporter, décrire.', 3),
    ('50088fdf-2021-5d7a-b7a3-b182d5d7779d'::uuid, 'a5b34236-2540-55ae-b6c1-89764b95738b'::uuid, 'Que désigne une URL ?', 'mcq', '["L’adresse unique d’une ressource sur le Web","Le nom d’un serveur","Un protocole de transport","Un moteur de recherche"]'::jsonb, 0, 'Protocole, domaine, chemin, paramètres.', 4),
    ('c4a011e6-6452-5b10-bd28-fa4c29c0dd0d'::uuid, 'a5b34236-2540-55ae-b6c1-89764b95738b'::uuid, 'Dans quel sens se lit un nom de domaine ?', 'mcq', '["De droite à gauche : extension, domaine, sous-domaine","De gauche à droite","Par ordre alphabétique","Selon le protocole utilisé"]'::jsonb, 0, 'L’extension est la partie la plus générale.', 5),
    ('d151dba3-bd02-5535-b719-dcdf094f6043'::uuid, 'a5b34236-2540-55ae-b6c1-89764b95738b'::uuid, 'Le Web forme un graphe de pages reliées par des liens.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Cette structure est exploitée par les moteurs de recherche.', 6),
    ('0e7a474c-411b-5c84-a838-b3877eea9509'::uuid, 'a5b34236-2540-55ae-b6c1-89764b95738b'::uuid, 'Qui a imaginé le Memex en 1945 ?', 'mcq', '["Vannevar Bush","Ted Nelson","Tim Berners-Lee","Alan Turing"]'::jsonb, 0, 'Une machine reliant les documents par associations.', 7),
    ('7534bdbf-9949-58b7-9c50-5c16ddab1e4b'::uuid, 'a5b34236-2540-55ae-b6c1-89764b95738b'::uuid, 'Pourquoi l’hypertexte est-il utile aux moteurs de recherche ?', 'mcq', '["Les liens entrants permettent d’estimer l’importance d’une page","Il accélère le chargement","Il chiffre le contenu","Il compresse les pages"]'::jsonb, 0, 'C’est le principe du PageRank.', 8),
    ('fcbf5d3c-a1b6-52c9-94f8-261be3d5e268'::uuid, 'a1925074-7ac2-5597-afd6-5ae25c211fb0'::uuid, 'Que signifie le code HTTP 404 ?', 'mcq', '["La ressource demandée est introuvable","La requête a réussi","Le serveur a rencontré une erreur","La page a été déplacée"]'::jsonb, 0, '200 = succès, 301 = redirection, 500 = erreur serveur.', 1),
    ('47b3079f-5216-5124-b203-bc22f493754e'::uuid, 'a1925074-7ac2-5597-afd6-5ae25c211fb0'::uuid, 'Qu’ajoute HTTPS par rapport à HTTP ?', 'mcq', '["Le chiffrement des échanges et l’authentification du site","Une meilleure vitesse","Une compression des images","Un référencement prioritaire"]'::jsonb, 0, 'Grâce à TLS et à un certificat.', 2),
    ('d914ee02-d26e-5e73-8fb8-cba4959df6ea'::uuid, 'a1925074-7ac2-5597-afd6-5ae25c211fb0'::uuid, 'À quoi sert le langage HTML ?', 'mcq', '["À décrire la structure et le contenu d’une page","À définir les couleurs et les polices","À rendre la page interactive","À transporter les données"]'::jsonb, 0, 'Il fonctionne à l’aide de balises.', 3),
    ('9ca5bd38-4e50-5604-8e86-2d6b846c6640'::uuid, 'a1925074-7ac2-5597-afd6-5ae25c211fb0'::uuid, 'À quoi sert le langage CSS ?', 'mcq', '["À définir la présentation des éléments de la page","À structurer le contenu","À interroger une base de données","À router les paquets"]'::jsonb, 0, 'Une feuille de style peut habiller des milliers de pages.', 4),
    ('edbc704b-496e-521c-99f8-615d71c3cdfb'::uuid, 'a1925074-7ac2-5597-afd6-5ae25c211fb0'::uuid, 'Quel langage rend une page interactive sans la recharger ?', 'mcq', '["JavaScript","HTML","CSS","HTTP"]'::jsonb, 0, 'Il s’exécute dans le navigateur et modifie la page.', 5),
    ('29d5ea07-dc19-51fd-b574-d91bf0c90a06'::uuid, 'a1925074-7ac2-5597-afd6-5ae25c211fb0'::uuid, 'Une page HTML bien structurée est mieux lue par les lecteurs d’écran.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’accessibilité dépend directement de la structure des balises.', 6),
    ('c64fd34f-2177-5c56-b748-ade980cc2bd7'::uuid, 'a1925074-7ac2-5597-afd6-5ae25c211fb0'::uuid, 'Comment fonctionne le protocole HTTP ?', 'mcq', '["Par requête du client et réponse du serveur","Par diffusion permanente du serveur","Par échange direct entre navigateurs","Par synchronisation périodique"]'::jsonb, 0, 'Chaque ressource fait l’objet d’une requête.', 7),
    ('5842e8d6-91bf-5961-9e48-90f48643086c'::uuid, 'a1925074-7ac2-5597-afd6-5ae25c211fb0'::uuid, 'Qu’appelle-t-on une page responsive ?', 'mcq', '["Une page dont la mise en forme s’adapte à la taille de l’écran","Une page qui se charge vite","Une page interactive","Une page traduite automatiquement"]'::jsonb, 0, 'Obtenue par des règles CSS conditionnelles.', 8),
    ('ea604371-b854-513b-bcec-db31ca6eee34'::uuid, '6fb18142-d419-56ff-92ea-e8c1969f1bb3'::uuid, 'Qu’est-ce qu’un cookie ?', 'mcq', '["Un petit fichier déposé par un site pour mémoriser des informations","Un virus informatique","Un fichier de cache d’image","Un protocole de transport"]'::jsonb, 0, 'Panier, session, préférences, mais aussi pistage.', 1),
    ('f5177089-ff41-582d-a319-5e4f13d0d73a'::uuid, '6fb18142-d419-56ff-92ea-e8c1969f1bb3'::uuid, 'À quoi servent les cookies tiers ?', 'mcq', '["À suivre la navigation d’un utilisateur d’un site à l’autre","À accélérer le chargement","À chiffrer la connexion","À bloquer la publicité"]'::jsonb, 0, 'Déposés par des régies présentes sur de nombreux sites.', 2),
    ('66ef75fc-fb5a-577a-bd02-91a41f2db7ea'::uuid, '6fb18142-d419-56ff-92ea-e8c1969f1bb3'::uuid, 'Que impose le RGPD depuis 2018 pour les cookies non nécessaires ?', 'mcq', '["Le consentement libre et éclairé de l’utilisateur","Leur interdiction totale","Leur suppression chaque semaine","Leur déclaration à la CNIL"]'::jsonb, 0, 'Refuser doit être aussi simple qu’accepter.', 3),
    ('04f402c9-e5e3-5185-b918-3dd42cf24552'::uuid, '6fb18142-d419-56ff-92ea-e8c1969f1bb3'::uuid, 'Qu’est-ce que le hameçonnage ?', 'mcq', '["Une imitation d’un site de confiance pour voler des identifiants","Un chiffrement des fichiers contre rançon","Une saturation de serveur","Une interception de paquets"]'::jsonb, 0, 'Il arrive le plus souvent par courriel ou SMS.', 4),
    ('62ba3c0a-58b7-52c0-9067-10f63e5c9739'::uuid, '6fb18142-d419-56ff-92ea-e8c1969f1bb3'::uuid, 'Qu’est-ce qu’un rançongiciel ?', 'mcq', '["Un logiciel qui chiffre les fichiers et exige une rançon","Un logiciel espion","Un bloqueur de publicité","Un antivirus payant"]'::jsonb, 0, 'La sauvegarde régulière est la meilleure protection.', 5),
    ('f6469f32-2948-5860-bb66-8e6447d5d469'::uuid, '6fb18142-d419-56ff-92ea-e8c1969f1bb3'::uuid, 'La navigation privée rend anonyme sur Internet.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle efface les traces locales, pas celles du site ni du fournisseur d’accès.', 6),
    ('6b6f81c9-ca6e-5cd2-97d9-4900e026eb2c'::uuid, '6fb18142-d419-56ff-92ea-e8c1969f1bb3'::uuid, 'Quelle protection ajoute une seconde preuve d’identité à la connexion ?', 'mcq', '["La double authentification","Le mot de passe long","Le chiffrement du disque","Le pare-feu"]'::jsonb, 0, 'Un code temporaire ou une clé physique.', 7),
    ('ce908ee9-d5a6-577f-b5ac-81704cc8d633'::uuid, '6fb18142-d419-56ff-92ea-e8c1969f1bb3'::uuid, 'Que vérifier avant de saisir un mot de passe sur un site ?', 'mcq', '["L’adresse exacte du site et la présence de HTTPS","La rapidité de chargement","La présence de publicité","La langue du site"]'::jsonb, 0, 'Un domaine légèrement modifié est le signe classique du hameçonnage.', 8),
    ('8a51952c-6cff-563e-9ce1-a22c416f2e43'::uuid, '597f4239-f189-59f6-8b25-ab438a6e361c'::uuid, 'Quelles sont les trois étapes du fonctionnement d’un moteur de recherche ?', 'mcq', '["Exploration, indexation, interrogation","Requête, chiffrement, réponse","Téléchargement, compression, affichage","Filtrage, classement, publication"]'::jsonb, 0, 'Tout est indexé avant que vous ne tapiez la requête.', 1),
    ('64418d09-3d6f-5066-a879-2b3ada2db866'::uuid, '597f4239-f189-59f6-8b25-ab438a6e361c'::uuid, 'Qu’est-ce qu’un crawler ?', 'mcq', '["Un robot qui parcourt le Web en suivant les liens","Un moteur de classement","Un serveur de cache","Un filtre anti-spam"]'::jsonb, 0, 'Il alimente l’index du moteur.', 2),
    ('3310431f-f786-5f75-b168-ae4ca6d8a0f7'::uuid, '597f4239-f189-59f6-8b25-ab438a6e361c'::uuid, 'Qu’est-ce qu’un index inversé ?', 'mcq', '["Une structure associant à chaque mot la liste des pages qui le contiennent","La liste des pages classées par date","Un annuaire de sites","Un historique de navigation"]'::jsonb, 0, 'C’est ce qui rend la recherche quasi instantanée.', 3),
    ('61ba51a8-806f-577d-a6cb-57ce565eabaa'::uuid, '597f4239-f189-59f6-8b25-ab438a6e361c'::uuid, 'Sur quoi repose le PageRank ?', 'mcq', '["Le nombre et la qualité des liens pointant vers une page","Le nombre de mots de la page","La date de création du site","Le nombre de visiteurs"]'::jsonb, 0, 'Une page est importante si des pages importantes la citent.', 4),
    ('1577b380-8349-5e4b-b6e2-6962fc0c4574'::uuid, '597f4239-f189-59f6-8b25-ab438a6e361c'::uuid, 'Deux personnes obtiennent-elles les mêmes résultats pour une même requête ?', 'mcq', '["Pas nécessairement, à cause de la personnalisation","Oui, toujours","Oui, sauf en navigation privée","Non, jamais"]'::jsonb, 0, 'Historique et localisation influent sur le classement.', 5),
    ('7f9430c7-7538-5171-b54b-85418157ee07'::uuid, '597f4239-f189-59f6-8b25-ab438a6e361c'::uuid, 'Les liens sponsorisés doivent être signalés comme publicité.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La loi impose de distinguer résultats naturels et payants.', 6),
    ('45bd1253-ce51-57f2-89d9-3373a989b888'::uuid, '597f4239-f189-59f6-8b25-ab438a6e361c'::uuid, 'Comment rechercher une expression exacte ?', 'mcq', '["En la plaçant entre guillemets","En la mettant en majuscules","En ajoutant un point d’exclamation","En la soulignant"]'::jsonb, 0, 'Le moteur cherche alors la suite de mots telle quelle.', 7),
    ('33451df8-d18e-53e6-866f-002847e398ba'::uuid, '597f4239-f189-59f6-8b25-ab438a6e361c'::uuid, 'Le premier résultat est-il la réponse la plus fiable ?', 'mcq', '["Non, c’est la mieux classée par un algorithme aux critères privés","Oui, par définition","Oui, s’il s’agit d’un site officiel","Non, c’est toujours une publicité"]'::jsonb, 0, 'Recouper les sources reste indispensable.', 8),
    ('f127ebfc-445a-5b14-9c5a-93879ef40287'::uuid, 'd937e6ff-c99e-5f31-875e-e0f79adc5150'::uuid, 'Qu’est-ce que le web 2.0 ?', 'mcq', '["Un Web où les utilisateurs produisent eux-mêmes le contenu","Une nouvelle version du protocole HTTP","Le Web chiffré","Le Web des objets connectés"]'::jsonb, 0, 'Blogs, wikis, réseaux sociaux, plateformes vidéo.', 1),
    ('a06e20e9-623c-5c1f-9076-04cb595725eb'::uuid, 'd937e6ff-c99e-5f31-875e-e0f79adc5150'::uuid, 'Qu’est-ce qu’un effet de réseau ?', 'mcq', '["La valeur d’un service augmente avec le nombre de ses utilisateurs","La vitesse augmente avec le débit","Le coût baisse avec le volume","La sécurité croît avec le chiffrement"]'::jsonb, 0, 'Il favorise la concentration en quelques très grands acteurs.', 2),
    ('1f0ac297-98f8-51ff-9fd2-7513e83099ed'::uuid, 'd937e6ff-c99e-5f31-875e-e0f79adc5150'::uuid, 'Quel projet illustre l’intelligence collective en cartographie ?', 'mcq', '["OpenStreetMap","Wikipédia","GitHub","Creative Commons"]'::jsonb, 0, 'Une carte mondiale construite par des contributeurs bénévoles.', 3),
    ('7b535bfd-61b3-5f41-8c0e-f77925ccc607'::uuid, 'd937e6ff-c99e-5f31-875e-e0f79adc5150'::uuid, 'Que sont les licences Creative Commons ?', 'mcq', '["Des licences permettant à un auteur d’autoriser certains usages de son œuvre","Des logiciels libres","Des contrats de plateforme","Des certificats de sécurité"]'::jsonb, 0, 'Elles précisent ce qui est permis sans demande préalable.', 4),
    ('c4c6bc0b-33d0-5a4b-b837-8a6ddd3d3262'::uuid, 'd937e6ff-c99e-5f31-875e-e0f79adc5150'::uuid, 'La contribution ouverte suffit-elle à garantir la qualité ?', 'mcq', '["Non, il faut des règles, une vérification et des contributeurs réguliers","Oui, le nombre corrige tout","Oui, si les contributeurs sont anonymes","Non, elle produit toujours de la désinformation"]'::jsonb, 0, 'Wikipédia repose sur des règles éditoriales strictes.', 5),
    ('fd754212-a953-5ebc-a1db-1f0105dac613'::uuid, 'd937e6ff-c99e-5f31-875e-e0f79adc5150'::uuid, 'Sur une plateforme gratuite, les données des utilisateurs constituent une ressource économique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le service est financé par la publicité ciblée.', 6),
    ('3612de76-7cf3-581c-804e-cdd21761c2eb'::uuid, 'd937e6ff-c99e-5f31-875e-e0f79adc5150'::uuid, 'Qu’est-ce que le contenu généré par les utilisateurs ?', 'mcq', '["Le contenu publié par les internautes eux-mêmes","Le contenu produit par des algorithmes","Le contenu payant","Le contenu indexé par les moteurs"]'::jsonb, 0, 'Il est devenu majoritaire sur le Web.', 7),
    ('cbe31025-ae66-5058-9fde-a6c789844561'::uuid, 'd937e6ff-c99e-5f31-875e-e0f79adc5150'::uuid, 'Quelle responsabilité pèse sur les grandes plateformes ?', 'mcq', '["La modération des contenus illicites qui leur sont signalés","La vérification de chaque publication avant mise en ligne","La rémunération de tous les contributeurs","Le stockage éternel des données"]'::jsonb, 0, 'Le cadre européen a été renforcé ces dernières années.', 8),
    ('39f4e980-63b5-5b47-b2da-06a4d4acae43'::uuid, '316bdb8c-e539-5bb4-86b2-b6437350159b'::uuid, 'Qu’est-ce qu’une donnée ouverte ?', 'mcq', '["Une donnée librement accessible, réutilisable et redistribuable","Une donnée publiée sur un site officiel","Une donnée gratuite mais non réutilisable","Une donnée anonymisée"]'::jsonb, 0, 'La licence doit autoriser explicitement la réutilisation.', 1),
    ('107e6255-f4c7-5d20-9863-0f6093084a70'::uuid, '316bdb8c-e539-5bb4-86b2-b6437350159b'::uuid, 'Quel format convient à l’open data ?', 'mcq', '["Un format ouvert et lisible par machine, comme CSV ou JSON","Un PDF scanné","Une image","Un document de traitement de texte propriétaire"]'::jsonb, 0, 'La lisibilité par machine est essentielle à la réutilisation.', 2),
    ('8e337c67-2ffb-5df3-88ab-e62e630031a0'::uuid, '316bdb8c-e539-5bb4-86b2-b6437350159b'::uuid, 'Quel portail rassemble les données publiques françaises ?', 'mcq', '["data.gouv.fr","service-public.fr","insee.fr","legifrance.fr"]'::jsonb, 0, 'Des milliers de jeux de données y sont publiés.', 3),
    ('974ebdae-5bac-514b-a58c-35ea3e839fe5'::uuid, '316bdb8c-e539-5bb4-86b2-b6437350159b'::uuid, 'Que sont les métadonnées ?', 'mcq', '["Des informations qui décrivent un jeu de données","Des données personnelles","Des données chiffrées","Des données en double"]'::jsonb, 0, 'Source, date, périmètre, unité de mesure, licence.', 4),
    ('39ddef11-f089-51aa-a7b0-85518fb18e7d'::uuid, '316bdb8c-e539-5bb4-86b2-b6437350159b'::uuid, 'Les données personnelles peuvent-elles être ouvertes telles quelles ?', 'mcq', '["Non, elles doivent être anonymisées et le risque de réidentification est réel","Oui, si elles sont publiques","Oui, avec l’accord du maire","Non, jamais sous aucune forme"]'::jsonb, 0, 'Le croisement de jeux anonymisés peut réidentifier des individus.', 5),
    ('0a95665d-0a71-5d97-8002-e737152c07a6'::uuid, '316bdb8c-e539-5bb4-86b2-b6437350159b'::uuid, 'La loi pour une République numérique de 2016 impose l’ouverture par défaut des données publiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sous réserve des secrets protégés par la loi.', 6),
    ('d30977c5-b49e-5e52-955a-778bcc7a1f28'::uuid, '316bdb8c-e539-5bb4-86b2-b6437350159b'::uuid, 'Quel usage concret l’open data permet-il ?', 'mcq', '["Des applications d’horaires de transport en temps réel","Le chiffrement des communications","La lutte contre les virus","L’accélération du réseau"]'::jsonb, 0, 'Comme les comparateurs de prix ou les cartes de qualité de l’air.', 7),
    ('7af00d4c-52ff-5146-9eb1-60dc2cc45839'::uuid, '316bdb8c-e539-5bb4-86b2-b6437350159b'::uuid, 'Quelle est la principale limite pratique de l’open data ?', 'mcq', '["La qualité inégale des jeux publiés et le coût de leur mise à jour","Le manque de serveurs","L’absence de logiciels de lecture","L’interdiction de réutilisation"]'::jsonb, 0, 'Un jeu non mis à jour perd rapidement toute utilité.', 8),
    ('29cc1f7c-3317-5b09-b965-7de8b5b74024'::uuid, '3663ec49-f8ec-57b5-9cde-61d551ade2bc'::uuid, 'Qu’est-ce que le cloud ?', 'mcq', '["La mise à disposition par le réseau de ressources informatiques hébergées ailleurs","Un logiciel de compression","Un réseau pair-à-pair","Un protocole de transport"]'::jsonb, 0, 'Stockage, calcul ou logiciel, facturés à l’usage.', 1),
    ('4e9da944-7bf1-5d1f-b7b7-1e990f4fdd28'::uuid, '3663ec49-f8ec-57b5-9cde-61d551ade2bc'::uuid, 'Qu’est-ce qu’un datacenter ?', 'mcq', '["Un bâtiment rassemblant des milliers de serveurs","Un logiciel de gestion de bases","Un centre d’appel","Un point d’échange Internet"]'::jsonb, 0, 'Avec alimentation, climatisation et réseau redondants.', 2),
    ('c82e9465-37cb-59b8-9fab-100b7b4454c6'::uuid, '3663ec49-f8ec-57b5-9cde-61d551ade2bc'::uuid, 'Pourquoi les données sont-elles répliquées ?', 'mcq', '["Pour survivre à une panne matérielle ou à un sinistre","Pour économiser de l’espace","Pour accélérer le chiffrement","Pour réduire la facture"]'::jsonb, 0, 'Souvent sur plusieurs sites distincts.', 3),
    ('851dbec0-a33c-5215-b8cf-d6e1971b3ecd'::uuid, '3663ec49-f8ec-57b5-9cde-61d551ade2bc'::uuid, 'Quel est l’un des principaux inconvénients du cloud ?', 'mcq', '["La dépendance à la connexion et au fournisseur","L’impossibilité de partager des fichiers","L’absence de sauvegarde","La lenteur de synchronisation"]'::jsonb, 0, 'Sans réseau, les données sont inaccessibles.', 4),
    ('789d7eb1-5375-56d9-a7fd-289df38a99d0'::uuid, '3663ec49-f8ec-57b5-9cde-61d551ade2bc'::uuid, 'Que désigne la question de la souveraineté des données ?', 'mcq', '["Le fait que la loi applicable dépende du lieu de stockage et de l’hébergeur","Le droit d’auteur sur les fichiers","Le chiffrement de bout en bout","Le coût du stockage"]'::jsonb, 0, 'Un enjeu majeur pour les administrations et les entreprises.', 5),
    ('059e7be5-9a1b-54b1-bcf8-c7d9ff430c65'::uuid, '3663ec49-f8ec-57b5-9cde-61d551ade2bc'::uuid, 'Le numérique représente environ 4 % des émissions mondiales de gaz à effet de serre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une part en croissance, dominée par la fabrication des terminaux.', 6),
    ('45fed5f6-0c9a-580c-8d77-de1f91e62ace'::uuid, '3663ec49-f8ec-57b5-9cde-61d551ade2bc'::uuid, 'Que mesure le PUE d’un datacenter ?', 'mcq', '["Le rapport entre l’énergie totale consommée et celle utile aux calculs","La puissance de calcul disponible","Le taux de disponibilité","La vitesse du réseau"]'::jsonb, 0, 'Plus il est proche de 1, plus le centre est efficace.', 7),
    ('6e932527-cbc3-5136-88a2-b4cb3a303d3c'::uuid, '3663ec49-f8ec-57b5-9cde-61d551ade2bc'::uuid, 'Où sont réellement stockées les données du cloud ?', 'mcq', '["Sur des disques, dans des datacenters appartenant à des entreprises","Dans l’atmosphère","Sur l’ordinateur de l’utilisateur","Sur les routeurs du réseau"]'::jsonb, 0, 'Le nuage est une métaphore, pas une description.', 8),
    ('e8605d92-a9b2-55ad-82f9-2066a8dfa972'::uuid, '68adac95-e12c-5530-a856-b3ca3691cc54'::uuid, 'Comment modélise-t-on un réseau social en mathématiques ?', 'mcq', '["Par un graphe, avec des sommets et des arêtes","Par un tableau de données","Par une équation","Par un arbre binaire"]'::jsonb, 0, 'Les sommets sont les personnes, les arêtes les relations.', 1),
    ('715ce31b-b9f5-5904-8a72-4b540e2ba42a'::uuid, '68adac95-e12c-5530-a856-b3ca3691cc54'::uuid, 'Qu’est-ce que le degré d’un sommet ?', 'mcq', '["Le nombre de ses voisins","La longueur du plus court chemin","Le nombre total de sommets","Sa position dans le graphe"]'::jsonb, 0, 'Un sommet de fort degré est très connecté.', 2),
    ('3274b186-8924-5646-a9d3-d8a6b6eb8292'::uuid, '68adac95-e12c-5530-a856-b3ca3691cc54'::uuid, 'Qu’est-ce que le diamètre d’un graphe ?', 'mcq', '["La plus grande distance entre deux sommets","Le nombre d’arêtes","Le degré maximal","Le nombre de communautés"]'::jsonb, 0, 'Dans les réseaux sociaux, il reste étonnamment faible.', 3),
    ('d48bb74b-78e9-5bf4-b5c7-38bd0c7caa81'::uuid, '68adac95-e12c-5530-a856-b3ca3691cc54'::uuid, 'Qui a mené l’expérience du petit monde en 1967 ?', 'mcq', '["Stanley Milgram","Mark Zuckerberg","Claude Shannon","Paul Erdős"]'::jsonb, 0, 'Des lettres à faire parvenir de proche en proche.', 4),
    ('2159dbfa-c238-5d52-83ce-f9968d087a62'::uuid, '68adac95-e12c-5530-a856-b3ca3691cc54'::uuid, 'Combien d’intermédiaires en moyenne dans l’expérience de Milgram ?', 'mcq', '["Environ six","Environ deux","Environ vingt","Environ cinquante"]'::jsonb, 0, 'D’où l’expression des six degrés de séparation.', 5),
    ('d1b7a348-7564-5210-96c7-85115aa183f8'::uuid, '68adac95-e12c-5530-a856-b3ca3691cc54'::uuid, 'Sur les grands réseaux sociaux, la distance moyenne est de l’ordre de quatre à cinq.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Mesurée sur des centaines de millions de comptes.', 6),
    ('7878dd3c-5ba6-5b75-a895-788666076dc3'::uuid, '68adac95-e12c-5530-a856-b3ca3691cc54'::uuid, 'Quels liens raccourcissent le plus les chemins dans un réseau ?', 'mcq', '["Les liens faibles, avec des connaissances lointaines","Les liens forts, avec les amis proches","Les liens familiaux","Les liens professionnels"]'::jsonb, 0, 'Ils relient des groupes qui, sinon, resteraient séparés.', 7),
    ('7c88d40e-5f44-5174-a96a-4ce8cdf60c1b'::uuid, '68adac95-e12c-5530-a856-b3ca3691cc54'::uuid, 'À quoi sert l’analyse des graphes sur un réseau social ?', 'mcq', '["À recommander des contacts, détecter des communautés et modéliser la diffusion","À chiffrer les messages","À compresser les images","À gérer les mots de passe"]'::jsonb, 0, 'Le même modèle décrit une rumeur ou une épidémie.', 8),
    ('843d074c-57fb-54b7-8f45-61bbf95906b3'::uuid, 'a0ffe21a-95b5-50c5-97bf-30f325aa8884'::uuid, 'Un fil d’actualité est-il chronologique ?', 'mcq', '["Non, il est classé par un algorithme","Oui, du plus récent au plus ancien","Oui, sauf pour les publicités","Non, il est aléatoire"]'::jsonb, 0, 'Le classement vise à maximiser l’engagement.', 1),
    ('addd9c72-ce94-5c48-afa5-7c454968c2b7'::uuid, 'a0ffe21a-95b5-50c5-97bf-30f325aa8884'::uuid, 'Qu’est-ce que le filtrage collaboratif ?', 'mcq', '["Recommander à un utilisateur ce qu’ont apprécié des utilisateurs similaires","Filtrer les contenus illégaux","Trier les messages par date","Bloquer les publicités"]'::jsonb, 0, 'La similarité est calculée sur les comportements passés.', 2),
    ('a1f7fc28-4c32-51f2-b81e-488d0c22f4bc'::uuid, 'a0ffe21a-95b5-50c5-97bf-30f325aa8884'::uuid, 'Qu’est-ce que la bulle de filtre ?', 'mcq', '["L’enfermement progressif dans des contenus conformes à ses opinions","Un filtre anti-spam","Une limite de débit","Un mode de navigation privée"]'::jsonb, 0, 'Notion popularisée par Eli Pariser.', 3),
    ('2ce9c2b5-924e-58c4-8abc-e551b0ca31ee'::uuid, 'a0ffe21a-95b5-50c5-97bf-30f325aa8884'::uuid, 'Qu’est-ce qu’une chambre d’écho ?', 'mcq', '["Un environnement social où l’on n’échange qu’avec des personnes du même avis","Un forum modéré","Un salon de discussion privé","Un groupe de travail"]'::jsonb, 0, 'Elle renforce les convictions et masque les avis contraires.', 4),
    ('2cc19d5e-e41d-56a9-907b-9e574061823b'::uuid, 'a0ffe21a-95b5-50c5-97bf-30f325aa8884'::uuid, 'Que cherche à maximiser un algorithme de recommandation ?', 'mcq', '["L’engagement, c’est-à-dire l’attention et le temps passé","La véracité de l’information","La diversité des points de vue","La rapidité de chargement"]'::jsonb, 0, 'Ce qui n’est pas la même chose que la qualité.', 5),
    ('d5f966c0-cae4-5f5c-a0fc-603c23ba0910'::uuid, 'a0ffe21a-95b5-50c5-97bf-30f325aa8884'::uuid, 'Une information fausse circule souvent plus vite qu’une information vérifiée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Parce qu’elle est plus surprenante et suscite plus d’émotion.', 6),
    ('3959d70d-585e-5db5-ab3b-ea42ec1d243f'::uuid, 'a0ffe21a-95b5-50c5-97bf-30f325aa8884'::uuid, 'Qu’est-ce que le biais de confirmation ?', 'mcq', '["La tendance à privilégier ce qui confirme ce qu’on croit déjà","La tendance à douter de tout","L’effet de la répétition d’un message","La confiance dans les sources officielles"]'::jsonb, 0, 'Il est puissamment renforcé par la personnalisation.', 7),
    ('6bea1859-93cd-5a96-82c6-16c493f487ea'::uuid, 'a0ffe21a-95b5-50c5-97bf-30f325aa8884'::uuid, 'Quel réflexe permet de vérifier l’origine d’une photo ?', 'mcq', '["La recherche d’image inversée","La lecture des commentaires","Le partage à des proches","Le zoom sur l’image"]'::jsonb, 0, 'Elle révèle souvent une image ancienne ou détournée.', 8),
    ('8e4f75c9-2122-5aca-a248-5dce7f8a0662'::uuid, '12feaaaa-219d-5c7e-81b6-2a9f1a893630'::uuid, 'Qu’est-ce qu’une trace involontaire ?', 'mcq', '["Une donnée laissée par la machine, comme l’adresse IP ou un cookie","Un message publié par erreur","Une photo prise par un ami","Un commentaire supprimé"]'::jsonb, 0, 'Elle est enregistrée sans action volontaire de l’utilisateur.', 1),
    ('c44f2811-e5b5-54c0-8489-2cdde6f24a2a'::uuid, '12feaaaa-219d-5c7e-81b6-2a9f1a893630'::uuid, 'Qu’est-ce qu’une trace héritée ?', 'mcq', '["Une trace laissée par d’autres à votre sujet","Une trace de votre enfance","Une trace effacée","Une trace chiffrée"]'::jsonb, 0, 'Une photo où vous êtes identifié, par exemple.', 2),
    ('301aaf99-c297-545e-975c-68ba3feaa3b9'::uuid, '12feaaaa-219d-5c7e-81b6-2a9f1a893630'::uuid, 'Depuis quand le RGPD est-il applicable ?', 'mcq', '["2018","2016","2020","2014"]'::jsonb, 0, 'Adopté en 2016, applicable en mai 2018.', 3),
    ('73d284fa-aa61-5941-8e17-24a8fdeee9b4'::uuid, '12feaaaa-219d-5c7e-81b6-2a9f1a893630'::uuid, 'Quel droit permet de demander l’effacement de ses données ?', 'mcq', '["Le droit à l’effacement, dit droit à l’oubli","Le droit d’accès","Le droit d’opposition","Le droit à la portabilité"]'::jsonb, 0, 'Il connaît des exceptions, notamment pour l’information du public.', 4),
    ('3f953781-7237-5dfe-b110-48ffdf0836f4'::uuid, '12feaaaa-219d-5c7e-81b6-2a9f1a893630'::uuid, 'Quelle autorité veille au respect des données personnelles en France ?', 'mcq', '["La CNIL","L’Arcom","L’Arcep","La DGCCRF"]'::jsonb, 0, 'Elle contrôle, conseille et sanctionne.', 5),
    ('516c01d5-dd89-5a50-9f76-214fcc13a7ca'::uuid, '12feaaaa-219d-5c7e-81b6-2a9f1a893630'::uuid, 'Supprimer un compte fait-il disparaître tout ce qui a été publié ?', 'mcq', '["Non, ce qui a été copié ou archivé subsiste","Oui, immédiatement","Oui, après trente jours","Non, mais les moteurs oublient tout"]'::jsonb, 0, 'Captures d’écran et archives échappent à la suppression.', 6),
    ('b7ba5765-29aa-552b-ab9f-6f8d6520cb76'::uuid, '12feaaaa-219d-5c7e-81b6-2a9f1a893630'::uuid, 'Le cyberharcèlement est un délit puni par la loi.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec des peines aggravées lorsque la victime est mineure.', 7),
    ('c44df346-948c-52a2-bdca-16d28059dbad'::uuid, '12feaaaa-219d-5c7e-81b6-2a9f1a893630'::uuid, 'Que suppose un consentement valable au sens du RGPD ?', 'mcq', '["Qu’il soit libre, spécifique, éclairé et révocable","Qu’il soit donné par écrit","Qu’il soit donné une fois pour toutes","Qu’il soit implicite"]'::jsonb, 0, 'Un consentement arraché par un bandeau piégeux n’est pas valable.', 8),
    ('1cbb2ff2-db8e-5b55-8a4d-ed23102bb982'::uuid, 'daf606fb-de13-5313-a4cb-ad12823cd311'::uuid, 'Qu’est-ce qu’un pixel ?', 'mcq', '["Le point élémentaire d’une image matricielle","Une unité de mesure de l’écran","Un format de fichier","Un niveau de compression"]'::jsonb, 0, 'Il porte une ou trois valeurs numériques.', 1),
    ('d02c9b95-1dda-5845-b22b-2c0d21ae384a'::uuid, 'daf606fb-de13-5313-a4cb-ad12823cd311'::uuid, 'Quelles sont les trois composantes du modèle RVB ?', 'mcq', '["Rouge, vert, bleu","Rouge, violet, blanc","Cyan, magenta, jaune","Rouge, vert, blanc"]'::jsonb, 0, 'La synthèse additive des écrans.', 2),
    ('4a6cbf26-0288-5f38-9f67-1859cc00ad0f'::uuid, 'daf606fb-de13-5313-a4cb-ad12823cd311'::uuid, 'Combien de niveaux par composante si elle est codée sur 8 bits ?', 'mcq', '["256","128","512","1024"]'::jsonb, 0, 'De 0 à 255.', 3),
    ('23116ef9-9f3b-533f-9154-abcaae25862c'::uuid, 'daf606fb-de13-5313-a4cb-ad12823cd311'::uuid, 'Combien de couleurs peut afficher un pixel codé en 24 bits ?', 'mcq', '["Environ 16,7 millions","Environ 65 000","256","Un nombre infini"]'::jsonb, 0, '256 puissance 3.', 4),
    ('4ff9212d-09cc-5e1b-b388-1cdee3507cbd'::uuid, 'daf606fb-de13-5313-a4cb-ad12823cd311'::uuid, 'Quel format compresse sans perte d’information ?', 'mcq', '["PNG","JPEG","GIF","WEBP en mode dégradé"]'::jsonb, 0, 'JPEG compresse avec perte, ce qui crée des artefacts.', 5),
    ('5e30abd7-c5dd-5657-9c64-337a4525902d'::uuid, 'daf606fb-de13-5313-a4cb-ad12823cd311'::uuid, 'Une image vectorielle peut être agrandie sans perte de qualité.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle décrit des formes par des équations, pas par des pixels.', 6),
    ('c1dc7e5e-9efd-50e6-b478-c5235daefaba'::uuid, 'daf606fb-de13-5313-a4cb-ad12823cd311'::uuid, 'Comment obtient-on un pixel blanc en RVB sur 8 bits ?', 'mcq', '["Trois composantes à 255","Trois composantes à 0","Rouge à 255 seulement","Bleu à 128"]'::jsonb, 0, 'Le noir correspond à trois zéros.', 7),
    ('f5d8aee6-0ac2-5c40-8787-746bafb36582'::uuid, 'daf606fb-de13-5313-a4cb-ad12823cd311'::uuid, 'Que contiennent les métadonnées EXIF d’une photo ?', 'mcq', '["L’appareil, la date et parfois la position GPS","Les couleurs dominantes","Le nom du photographe uniquement","Le taux de compression seulement"]'::jsonb, 0, 'Elles peuvent révéler des informations personnelles.', 8),
    ('0342f1fc-dd38-58c4-b553-8126b597c858'::uuid, '3aa81683-ea09-5342-863a-b720774ecb3c'::uuid, 'Comment convertit-on un pixel couleur en niveau de gris ?', 'mcq', '["En remplaçant les trois composantes par une valeur unique","En supprimant la composante bleue","En mettant toutes les composantes à 255","En doublant la composante rouge"]'::jsonb, 0, 'Moyenne simple ou luminance pondérée.', 1),
    ('b18cfb68-c49b-5a2b-bd26-6784add952b5'::uuid, '3aa81683-ea09-5342-863a-b720774ecb3c'::uuid, 'Pourquoi pondère-t-on davantage le vert dans le calcul de luminance ?', 'mcq', '["Parce que l’œil humain y est plus sensible","Parce qu’il occupe plus de bits","Parce que les écrans l’affichent mieux","Par convention arbitraire"]'::jsonb, 0, 'Le résultat est plus fidèle à la perception.', 2),
    ('fa26ba81-97da-5cca-9848-836216564a4e'::uuid, '3aa81683-ea09-5342-863a-b720774ecb3c'::uuid, 'Comment obtient-on le négatif d’un pixel codé sur 8 bits ?', 'mcq', '["En remplaçant chaque composante par 255 moins sa valeur","En divisant chaque composante par deux","En inversant l’ordre des composantes","En mettant tout à zéro"]'::jsonb, 0, 'L’opération est réversible.', 3),
    ('9638057e-b55f-56c2-8c31-07c050561a00'::uuid, '3aa81683-ea09-5342-863a-b720774ecb3c'::uuid, 'Qu’est-ce que le seuillage ?', 'mcq', '["Transformer l’image en noir et blanc pur selon une valeur limite","Réduire la taille du fichier","Augmenter le contraste progressivement","Ajouter du flou"]'::jsonb, 0, 'Il sépare la forme du fond.', 4),
    ('cb3b49b4-1d7f-51dc-8a9d-6e22f63fb53b'::uuid, '3aa81683-ea09-5342-863a-b720774ecb3c'::uuid, 'À quoi sert principalement le seuillage ?', 'mcq', '["À la reconnaissance de formes et de caractères","À la compression","À la colorisation","À l’agrandissement"]'::jsonb, 0, 'Il simplifie l’image avant analyse.', 5),
    ('00c08760-e0aa-5189-8788-dbc9313f3a93'::uuid, '3aa81683-ea09-5342-863a-b720774ecb3c'::uuid, 'Appliquer deux fois le négatif redonne l’image d’origine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La transformation est son propre inverse.', 6),
    ('e2fe5268-aab6-56f7-a01f-622d1a79475c'::uuid, '3aa81683-ea09-5342-863a-b720774ecb3c'::uuid, 'Que vaut la colorisation automatique d’une photo ancienne ?', 'mcq', '["Un résultat vraisemblable, mais non véridique","Les couleurs réelles retrouvées","Une image aléatoire","Une simple teinte sépia"]'::jsonb, 0, 'Le modèle invente des couleurs plausibles.', 7),
    ('eee72a45-ade7-523c-9f66-047d6ae13115'::uuid, '3aa81683-ea09-5342-863a-b720774ecb3c'::uuid, 'Une retouche d’image est-elle autre chose qu’un calcul sur des nombres ?', 'mcq', '["Non, c’est une fonction appliquée à chaque pixel","Oui, c’est un procédé optique","Oui, c’est une compression","Non, c’est une simple copie"]'::jsonb, 0, 'Tout filtre se ramène à une opération sur le tableau de valeurs.', 8),
    ('846d2a82-8ca4-5712-8f61-8b73fbc10d5e'::uuid, '79012fbb-bd08-5d5e-9b62-450298e2d336'::uuid, 'Que représente l’histogramme d’une image ?', 'mcq', '["Le nombre de pixels pour chaque valeur possible","La taille du fichier","La répartition des couleurs sur la surface","Le nombre de pixels de l’image"]'::jsonb, 0, 'Un diagnostic de la répartition des tons.', 1),
    ('206a0faf-cca5-54d7-9efa-579e1c9c84d0'::uuid, '79012fbb-bd08-5d5e-9b62-450298e2d336'::uuid, 'À quoi ressemble l’histogramme d’une image sous-exposée ?', 'mcq', '["Il est tassé vers la gauche","Il est tassé vers la droite","Il est parfaitement plat","Il est centré"]'::jsonb, 0, 'Les tons sombres dominent.', 2),
    ('9f344b61-c875-542e-9dfc-00cd3cb1f47a'::uuid, '79012fbb-bd08-5d5e-9b62-450298e2d336'::uuid, 'Que fait l’étirement d’histogramme ?', 'mcq', '["Il étale les valeurs occupées sur toute la plage disponible","Il supprime les pixels extrêmes","Il réduit le nombre de couleurs","Il compresse le fichier"]'::jsonb, 0, 'Le contraste augmente sans inventer d’information.', 3),
    ('44558ad2-fbdc-5577-ba07-af89de9798ac'::uuid, '79012fbb-bd08-5d5e-9b62-450298e2d336'::uuid, 'Que fait l’égalisation d’histogramme ?', 'mcq', '["Elle redistribue les valeurs pour aplatir l’histogramme","Elle inverse les couleurs","Elle floute l’image","Elle réduit la résolution"]'::jsonb, 0, 'Elle révèle des détails, au risque d’accentuer le bruit.', 4),
    ('f9fda194-b96b-505c-a05b-8aae9bb5fc58'::uuid, '79012fbb-bd08-5d5e-9b62-450298e2d336'::uuid, 'Dans quel domaine l’égalisation est-elle particulièrement utile ?', 'mcq', '["En imagerie médicale, satellitaire ou astronomique","En impression papier","En compression vidéo","En transmission réseau"]'::jsonb, 0, 'Elle fait apparaître des structures peu contrastées.', 5),
    ('4cf97768-accf-5c7b-93e7-1addba14a20f'::uuid, '79012fbb-bd08-5d5e-9b62-450298e2d336'::uuid, 'Une zone totalement surexposée peut être récupérée par traitement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’information a été perdue : aucun calcul ne la recrée.', 6),
    ('c999a4b5-c2c5-5a81-87ee-e13fae3cf7ee'::uuid, '79012fbb-bd08-5d5e-9b62-450298e2d336'::uuid, 'Que signifie un histogramme resserré au centre ?', 'mcq', '["L’image manque de contraste","L’image est surexposée","L’image est sous-exposée","L’image est saturée"]'::jsonb, 0, 'Ni noirs profonds ni blancs francs.', 7),
    ('96d080ec-9d20-5daa-8321-f3ff825de449'::uuid, '79012fbb-bd08-5d5e-9b62-450298e2d336'::uuid, 'Pourquoi les photographes surveillent-ils l’histogramme plutôt que l’écran ?', 'mcq', '["Parce que la luminosité de l’écran trompe l’œil","Parce que l’écran est trop petit","Parce que l’histogramme est plus rapide","Parce que l’écran ne montre pas les couleurs"]'::jsonb, 0, 'L’histogramme est une mesure, l’écran une impression.', 8),
    ('23896b12-6afa-5646-a82d-a680784f98c0'::uuid, 'a31555e4-1032-5714-a7ef-d9526f5afb10'::uuid, 'Quelle différence entre définition et résolution ?', 'mcq', '["La définition compte les pixels, la résolution dit à quelle densité ils sont restitués","Ce sont deux synonymes","La définition concerne l’impression","La résolution est le poids du fichier"]'::jsonb, 0, 'La résolution s’exprime en points par pouce.', 1),
    ('4edf600b-a72f-5698-9039-48105736d931'::uuid, 'a31555e4-1032-5714-a7ef-d9526f5afb10'::uuid, 'Agrandir une image ajoute-t-il du détail ?', 'mcq', '["Non, l’algorithme interpole à partir des pixels voisins","Oui, si le format est vectoriel","Oui, avec un bon logiciel","Non, cela réduit la taille"]'::jsonb, 0, 'L’information absente ne se recrée pas.', 2),
    ('7653aed8-d87e-5dae-a046-c96889dde81a'::uuid, 'a31555e4-1032-5714-a7ef-d9526f5afb10'::uuid, 'Qu’est-ce qu’un noyau de convolution ?', 'mcq', '["Une petite matrice définissant comment combiner les pixels voisins","Le centre de l’image","Un format de compression","Le pixel le plus lumineux"]'::jsonb, 0, 'Il définit l’effet du filtre.', 3),
    ('fc664081-427f-5c01-bef1-05c05585ce2c'::uuid, 'a31555e4-1032-5714-a7ef-d9526f5afb10'::uuid, 'Quel effet produit un noyau de moyenne ?', 'mcq', '["Un flou","Une netteté accrue","Une détection de contours","Une inversion des couleurs"]'::jsonb, 0, 'Chaque pixel prend la moyenne de son voisinage.', 4),
    ('695f5358-de23-5175-ba9a-0180bc04fc45'::uuid, 'a31555e4-1032-5714-a7ef-d9526f5afb10'::uuid, 'À quoi sert la détection de contours ?', 'mcq', '["À repérer les variations brutales de valeur, donc les formes","À augmenter la résolution","À compresser le fichier","À corriger l’exposition"]'::jsonb, 0, 'Base de la reconnaissance de caractères et de l’imagerie médicale.', 5),
    ('300627ea-a2fb-5c1c-8a6d-adf8a7bb4511'::uuid, 'a31555e4-1032-5714-a7ef-d9526f5afb10'::uuid, 'Réduire la définition d’une image supprime définitivement de l’information.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La remonter ensuite ne restaure pas les détails.', 6),
    ('0adf9540-2a83-5065-b4d1-28b7a4e70fa9'::uuid, 'a31555e4-1032-5714-a7ef-d9526f5afb10'::uuid, 'Pourquoi une image imprimée en grand format paraît-elle floue ?', 'mcq', '["Ses pixels s’étalent sur une plus grande surface","L’encre se disperse","La compression augmente","Le format change"]'::jsonb, 0, 'La résolution effective baisse.', 7),
    ('bca763cc-31c0-5f2f-9671-aea5ef588c5d'::uuid, 'a31555e4-1032-5714-a7ef-d9526f5afb10'::uuid, 'Quel traitement réduit le bruit d’une photo prise dans l’obscurité ?', 'mcq', '["Un filtre de lissage","Un seuillage","Une égalisation d’histogramme","Un agrandissement"]'::jsonb, 0, 'Au prix d’une légère perte de détail.', 8),
    ('0d268fdc-399c-5ab6-b0ac-829632e84df4'::uuid, 'd61446bd-a2ff-55b9-81a6-ae1db971bec8'::uuid, 'Qu’est-ce qu’un photosite ?', 'mcq', '["Une cellule du capteur qui accumule une charge proportionnelle à la lumière reçue","Un pixel de l’écran","Un filtre coloré","Un point de mise au point"]'::jsonb, 0, 'Des millions de photosites forment le capteur.', 1),
    ('9daeede3-b4f6-5e7e-8c81-c6506a24a0e7'::uuid, 'd61446bd-a2ff-55b9-81a6-ae1db971bec8'::uuid, 'Quelle technologie équipe la plupart des capteurs actuels ?', 'mcq', '["CMOS","CCD","LCD","OLED"]'::jsonb, 0, 'Moins gourmande en énergie et moins coûteuse que le CCD.', 2),
    ('e1735a07-062f-5ddd-94bb-9d95c14a85fe'::uuid, 'd61446bd-a2ff-55b9-81a6-ae1db971bec8'::uuid, 'Un photosite perçoit-il directement la couleur ?', 'mcq', '["Non, il compte la lumière derrière un filtre coloré","Oui, les trois composantes","Oui, avec un prisme intégré","Non, il ne perçoit que le contraste"]'::jsonb, 0, 'La couleur est reconstruite par calcul.', 3),
    ('2cb92b5f-0452-5df4-a586-41f3416c6c0b'::uuid, 'd61446bd-a2ff-55b9-81a6-ae1db971bec8'::uuid, 'Quelle est la particularité de la matrice de Bayer ?', 'mcq', '["Elle compte deux filtres verts pour un rouge et un bleu","Elle alterne rouge et bleu seulement","Elle utilise quatre couleurs égales","Elle n’utilise aucun filtre"]'::jsonb, 0, 'Parce que l’œil est plus sensible au vert.', 4),
    ('524a4062-f22d-570b-8519-1f650726cb53'::uuid, 'd61446bd-a2ff-55b9-81a6-ae1db971bec8'::uuid, 'Qu’est-ce que le dématriçage ?', 'mcq', '["L’algorithme qui reconstitue les trois composantes de chaque pixel","La compression du fichier","Le nettoyage du capteur","La correction de l’exposition"]'::jsonb, 0, 'Il s’appuie sur les valeurs des photosites voisins.', 5),
    ('a6761cd3-24c1-5adb-8cf4-178a43b9c875'::uuid, 'd61446bd-a2ff-55b9-81a6-ae1db971bec8'::uuid, 'Le format RAW conserve les données du capteur avant traitement.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il offre plus de latitude en retouche, au prix d’un fichier lourd.', 6),
    ('bae7f5f6-c2fe-58e7-84ba-6b206a072af7'::uuid, 'd61446bd-a2ff-55b9-81a6-ae1db971bec8'::uuid, 'Qu’est-ce qui détermine le plus la qualité d’une image ?', 'mcq', '["La taille du capteur et des photosites, plus que le nombre de mégapixels","Le seul nombre de mégapixels","La taille de l’écran","Le format de fichier"]'::jsonb, 0, 'De gros photosites captent plus de lumière et génèrent moins de bruit.', 7),
    ('80302cb7-c06a-5416-a67c-97aebfe44af3'::uuid, 'd61446bd-a2ff-55b9-81a6-ae1db971bec8'::uuid, 'Que provoque une montée de la sensibilité du capteur ?', 'mcq', '["L’apparition de bruit dans l’image","Une perte de définition","Un décalage des couleurs uniquement","Un agrandissement automatique"]'::jsonb, 0, 'Le signal est amplifié, les parasites aussi.', 8),
    ('52d7f071-a944-51a8-8d17-3a6db1f3c005'::uuid, 'ee279854-b2b7-5bfa-90e8-82f97ec996c9'::uuid, 'Comment un récepteur GPS calcule-t-il sa distance à un satellite ?', 'mcq', '["En comparant l’heure d’émission du signal à l’heure de réception","En mesurant la puissance du signal","En calculant un angle","En interrogeant le satellite"]'::jsonb, 0, 'La distance se déduit du temps de parcours.', 1),
    ('9aac7dd4-4b72-5012-b3d7-a48d0dd283e8'::uuid, 'ee279854-b2b7-5bfa-90e8-82f97ec996c9'::uuid, 'Combien de satellites faut-il au minimum pour une position complète ?', 'mcq', '["Quatre","Trois","Deux","Six"]'::jsonb, 0, 'Le quatrième corrige l’imprécision de l’horloge du récepteur.', 2),
    ('298a6925-34bc-5529-b67c-66f9a672b22f'::uuid, 'ee279854-b2b7-5bfa-90e8-82f97ec996c9'::uuid, 'Comment s’appelle le système européen de positionnement ?', 'mcq', '["Galileo","GLONASS","Beidou","Copernicus"]'::jsonb, 0, 'GLONASS est russe, Beidou chinois.', 3),
    ('b2a6e542-7de2-59b2-98ef-5f0af306fe69'::uuid, 'ee279854-b2b7-5bfa-90e8-82f97ec996c9'::uuid, 'Le récepteur émet-il un signal vers les satellites ?', 'mcq', '["Non, il se contente de recevoir","Oui, pour s’identifier","Oui, une fois par minute","Non, mais il émet vers les antennes relais"]'::jsonb, 0, 'C’est pourquoi le GPS fonctionne sans abonnement.', 4),
    ('53a42072-0c62-5915-a5a1-f9836a3e1a16'::uuid, 'ee279854-b2b7-5bfa-90e8-82f97ec996c9'::uuid, 'Qu’est-ce qui dégrade la précision en ville ?', 'mcq', '["La réflexion des signaux sur les façades","La densité de population","Le nombre de téléphones connectés","La pollution atmosphérique"]'::jsonb, 0, 'Les trajets multiples faussent les temps de parcours.', 5),
    ('21d89344-1345-5e59-ba07-994c7076ad63'::uuid, 'ee279854-b2b7-5bfa-90e8-82f97ec996c9'::uuid, 'Un téléphone utilise aussi le wifi et les antennes mobiles pour se localiser.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ce qui améliore la position en intérieur et en ville.', 6),
    ('6a00735c-d1ed-57be-90d7-d32f02d65d76'::uuid, 'ee279854-b2b7-5bfa-90e8-82f97ec996c9'::uuid, 'Pourquoi les satellites embarquent-ils des horloges atomiques ?', 'mcq', '["Parce qu’une erreur infime de temps produit une grande erreur de distance","Pour économiser l’énergie","Pour synchroniser les orbites","Pour chiffrer le signal"]'::jsonb, 0, 'Le signal voyage à la vitesse de la lumière.', 7),
    ('786dc36f-7344-59b9-ac36-2dd8dc34e2f0'::uuid, 'ee279854-b2b7-5bfa-90e8-82f97ec996c9'::uuid, 'Pourquoi la position est-elle une donnée sensible ?', 'mcq', '["Elle révèle domicile, travail, habitudes et fréquentations","Elle est difficile à mesurer","Elle change tout le temps","Elle est publique par nature"]'::jsonb, 0, 'D’où l’importance de limiter les autorisations accordées aux applications.', 8),
    ('aed9487b-57ef-52f3-bfaa-f123481ca8eb'::uuid, '24ab8a47-7d3a-5506-b9cc-3ac7efd38a90'::uuid, 'Comment un réseau routier est-il modélisé pour un calcul d’itinéraire ?', 'mcq', '["Par un graphe pondéré, intersections et tronçons","Par une image satellite","Par un tableau de coordonnées","Par une liste d’adresses"]'::jsonb, 0, 'Chaque arête porte un poids.', 1),
    ('6f325636-62d4-5d17-8773-0019650af1b9'::uuid, '24ab8a47-7d3a-5506-b9cc-3ac7efd38a90'::uuid, 'Que peut représenter le poids d’une arête ?', 'mcq', '["La distance, la durée, un péage ou une contrainte","Uniquement la distance","Le nombre de voitures","La largeur de la route"]'::jsonb, 0, 'Changer le poids change l’itinéraire calculé.', 2),
    ('b32c8a50-bb25-55f0-9836-b4e7ec46e19d'::uuid, '24ab8a47-7d3a-5506-b9cc-3ac7efd38a90'::uuid, 'Que calcule l’algorithme de Dijkstra ?', 'mcq', '["Le plus court chemin d’un sommet vers tous les autres","Le chemin le plus long","Le nombre de chemins possibles","Le centre du graphe"]'::jsonb, 0, 'À condition que les poids soient positifs.', 3),
