    ('b9ad2434-153f-5a8d-84f0-625cac27805c'::uuid, 'd199fb1f-8926-5b1e-a9af-82d4d147ebf7'::uuid, 'Quels sont les trois organes d’un système automatisé ?', 'mcq', '["Capteurs, partie commande, actionneurs","Écran, clavier, souris","Processeur, mémoire, disque","Réseau, serveur, client"]'::jsonb, 0, 'Capter, décider, agir.', 1),
    ('9f37f761-587c-504d-9308-5f1a68c0c916'::uuid, 'd199fb1f-8926-5b1e-a9af-82d4d147ebf7'::uuid, 'Que fait un capteur ?', 'mcq', '["Il transforme une grandeur physique en signal exploitable","Il agit sur le monde extérieur","Il exécute le programme","Il alimente le système"]'::jsonb, 0, 'Température, lumière, distance, présence.', 2),
