    ('0986d14b-00d7-50d0-9604-0a421524e85f'::uuid, 'd199fb1f-8926-5b1e-a9af-82d4d147ebf7'::uuid, 'Qu’est-ce qu’une boucle fermée ?', 'mcq', '["Un système qui mesure l’effet de son action et corrige","Un système sans capteur","Un système sans programme","Un circuit électrique fermé"]'::jsonb, 0, 'C’est le principe de la rétroaction.', 4),
    ('6646147d-cea8-5c43-9e9c-79f853f3be99'::uuid, 'd199fb1f-8926-5b1e-a9af-82d4d147ebf7'::uuid, 'Quel exemple illustre la boucle ouverte ?', 'mcq', '["Un grille-pain à minuterie","Un thermostat","Un régulateur de vitesse","Un pilote automatique"]'::jsonb, 0, 'Il exécute sans vérifier le résultat obtenu.', 5),
