    ('816ce20f-d680-5b0b-9ef9-e9f48fab9920'::uuid, 'd199fb1f-8926-5b1e-a9af-82d4d147ebf7'::uuid, 'Quelle question juridique posent les véhicules autonomes ?', 'mcq', '["La responsabilité en cas d’accident","Le droit d’auteur du logiciel","La protection des marques","Le régime de la copropriété"]'::jsonb, 0, 'Constructeur, éditeur, conducteur : le partage reste débattu.', 8),
    ('754bf33b-bd0e-563c-a14d-9fa93c333dfd'::uuid, 'a40d9c14-cf25-55ca-9ccc-7bea5e97f93f'::uuid, 'Qu’est-ce que l’Internet des objets ?', 'mcq', '["L’extension du réseau à des objets capables de mesurer et de communiquer","Un nouveau protocole de transport","Un réseau réservé aux entreprises","Un moteur de recherche d’objets"]'::jsonb, 0, 'Montres, ampoules, compteurs, capteurs industriels.', 1),
