    ('fe6f6be3-4c85-549d-827b-af576fb9ff0f'::uuid, 'a40d9c14-cf25-55ca-9ccc-7bea5e97f93f'::uuid, 'Pourquoi IPv6 est-il important pour l’IoT ?', 'mcq', '["Il offre un nombre d’adresses pratiquement illimité","Il est plus rapide qu’IPv4","Il chiffre les échanges","Il réduit la consommation"]'::jsonb, 0, 'Des milliards d’objets ont besoin d’adresses.', 3),
